rules.logic:
// Prevent duplicate injection
if (element.nextElementSibling && element.nextElementSibling.id === 'custom-category-tags') return;

const headline = element.textContent.toLowerCase();

// --- Tag definitions: label, search/topic URL, icon, color theme ---
const ALL_TAGS = [
  // Space & Astronomy bucket
  { label: '🚀 Space',       url: '/news/space',            match: /\b(space|cosmos|cosmic|universe|galaxy|solar|orbit|rocket|nasa|esa|hubble|telescope|satellite|asteroid|meteor|comet|nebula|star|stellar|black hole|dark matter)\b/ },
  { label: '🔭 Astronomy',   url: '/news/space',            match: /\b(astronomy|astrono|hubble|telescope|observ|celestial|milky way|constellation|planet|exoplanet|moon|sun|star|stellar|nebula|pulsar|quasar)\b/ },
  { label: '🪐 Exoplanets',  url: '/news/space',            match: /\b(exoplanet|worlds?|planet|kepler|jwst|james webb|solar system|orbit|habitable|alien|extraterrestrial)\b/ },
  // Weather & Storm bucket
  { label: '⛈️ Severe Storms', url: '/severe-weather',    match: /\b(hurricane|tornado|storm|cyclone|typhoon|blizzard|thunderstorm|lightning|hail|flood|twister|severe)\b/ },
  { label: '🌊 Climate',     url: '/news/climate',          match: /\b(climate|global warming|temperature|sea level|carbon|emission|greenhouse|ice|arctic|polar)\b/ },
  { label: '☀️ Seasonal',    url: '/news/seasonal',         match: /\b(summer|winter|spring|fall|autumn|season|solstice|equinox|heatwave|heat wave|cold snap|freeze)\b/ },
  // Nature bucket
  { label: '🦁 Animals',     url: '/news/animals',          match: /\b(animal|wildlife|species|bird|mammal|fish|reptile|insect|creature|fauna|wolf|bear|shark|whale)\b/ },
  { label: '🌿 Nature',      url: '/news/nature',           match: /\b(nature|forest|ocean|mountain|river|ecosystem|environment|habitat|tree|plant|flower|coral|reef)\b/ },
  // Science & Tech
  { label: '🔬 Science',     url: '/news/science',          match: /\b(science|scientif|research|study|discover|breakthrough|experiment|lab|dna|gene|biology|chemistry|physics|milestone)\b/ },
  { label: '💻 Technology',  url: '/news/technology',       match: /\b(technolog|ai|robot|software|computer|digital|innovation|engineer|machine|internet|data)\b/ },
  // Other
  { label: '✈️ Travel',      url: '/news/travel',           match: /\b(travel|trip|destination|vacation|holiday|explore|adventure|journey|tourism|beach|hike)\b/ },
  { label: '🏡 Home',        url: '/news/home-garden',      match: /\b(home|garden|house|indoor|outdoor|yard|plant|diy|decor|renovation|lawn)\b/ },
  { label: '🌪️ Viral',       url: '/news/viral',            match: /\b(viral|amazing|incredible|weird|bizarre|unusual|shocking|stunning|extraordinary|unbeliev|counting)\b/ },
];

const matched = ALL_TAGS.filter(t => t.match.test(headline));

// Always show at least the top 3 most relevant (up to 5)
const tags = matched.slice(0, 5);
if (tags.length === 0) return;

// Build the tag bar
const bar = document.createElement('div');
bar.id = 'custom-category-tags';
bar.style.cssText = [
  'display:flex',
  'flex-wrap:wrap',
  'align-items:center',
  'gap:8px',
  'margin:10px 0 4px 0',
  'padding:10px 14px',
  'background:linear-gradient(135deg,#f0f4ff 0%,#eaf6ff 100%)',
  'border-radius:14px',
  'border:1.5px solid #d0e3ff',
  'box-shadow:0 2px 8px rgba(58,97,204,0.08)',
  'font-family:inherit',
].join(';');

// Label
const label = document.createElement('span');
label.textContent = 'TOPICS:';
label.style.cssText = [
  'font-size:10px',
  'font-weight:800',
  'letter-spacing:0.12em',
  'color:#6b7faa',
  'text-transform:uppercase',
  'margin-right:2px',
  'flex-shrink:0',
].join(';');
bar.appendChild(label);

// Colour palette cycling
const palettes = [
  { bg:'#1a3ccc', text:'#ffffff', hover:'#0f2899' },
  { bg:'#7c3aed', text:'#ffffff', hover:'#5b21b6' },
  { bg:'#0891b2', text:'#ffffff', hover:'#0e7490' },
  { bg:'#059669', text:'#ffffff', hover:'#047857' },
  { bg:'#dc2626', text:'#ffffff', hover:'#b91c1c' },
];

tags.forEach((tag, i) => {
  const palette = palettes[i % palettes.length];
  const a = document.createElement('a');
  a.href = tag.url;
  a.textContent = tag.label;
  a.title = 'Browse more ' + tag.label.replace(/^[^\w]+/, '') + ' stories';
  a.style.cssText = [
    'display:inline-flex',
    'align-items:center',
    'padding:5px 13px',
    'border-radius:999px',
    'font-size:13px',
    'font-weight:700',
    'line-height:1.4',
    'text-decoration:none',
    'cursor:pointer',
    'transition:transform 0.15s,box-shadow 0.15s,background 0.15s',
    'background:' + palette.bg,
    'color:' + palette.text,
    'box-shadow:0 2px 6px rgba(0,0,0,0.18)',
    'letter-spacing:0.01em',
    'white-space:nowrap',
  ].join(';');

  a.onmouseenter = () => {
    a.style.background = palette.hover;
    a.style.transform = 'translateY(-2px) scale(1.04)';
    a.style.boxShadow = '0 6px 16px rgba(0,0,0,0.22)';
  };
  a.onmouseleave = () => {
    a.style.background = palette.bg;
    a.style.transform = '';
    a.style.boxShadow = '0 2px 6px rgba(0,0,0,0.18)';
  };

  bar.appendChild(a);
});

// Insert right after the h1
element.insertAdjacentElement('afterend', bar);
